// SecurityConfig.java
@Configuration
public class SecurityConfig {

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder(12); // cost factor 12
    }
}

// UserService.java
@Service
public class UserService {

    @Autowired
    private PasswordEncoder passwordEncoder;  // inject the bean

    @Autowired
    private UserRepository userRepository;

    public User register(String username, String rawPassword) {
        String hashedPassword = passwordEncoder.encode(rawPassword); // HASH
        User user = new User(username, hashedPassword); // store hash, not raw
        return userRepository.save(user);
    }
}

// AuthService.java (for manual login verification)
public boolean verifyPassword(String rawPassword, String storedHash) {
    return passwordEncoder.matches(rawPassword, storedHash); // returns true/false
}
```

